package com.lcl.myaiagent.controller;
import com.lcl.myaiagent.common.*; import com.lcl.myaiagent.model.dto.*; import com.lcl.myaiagent.model.po.User; import com.lcl.myaiagent.model.vo.InterviewSessionVO; import com.lcl.myaiagent.service.*; import jakarta.servlet.http.HttpServletRequest; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/interviews") @RequiredArgsConstructor public class InterviewController { private final InterviewService service; private final UserService users; @PostMapping public BaseResponse<InterviewSessionVO> start(@RequestBody InterviewStartRequest r,HttpServletRequest q){User u=users.getLoginUser(q);return ResultUtils.success(service.start(r.getTopic(),r.getQuestionLimit(),u));}@PostMapping("/{id}/answers") public BaseResponse<InterviewSessionVO> answer(@PathVariable String id,@RequestBody InterviewAnswerRequest r,HttpServletRequest q){return ResultUtils.success(service.answer(id,r.getAnswer(),users.getLoginUser(q)));}@PostMapping("/{id}/pause") public BaseResponse<InterviewSessionVO> pause(@PathVariable String id,HttpServletRequest q){return ResultUtils.success(service.pause(id,users.getLoginUser(q)));}@PostMapping("/{id}/resume") public BaseResponse<InterviewSessionVO> resume(@PathVariable String id,HttpServletRequest q){return ResultUtils.success(service.resume(id,users.getLoginUser(q)));}@GetMapping("/{id}") public BaseResponse<InterviewSessionVO> get(@PathVariable String id,HttpServletRequest q){return ResultUtils.success(service.get(id,users.getLoginUser(q)));}@GetMapping public BaseResponse<List<InterviewSessionVO>> list(HttpServletRequest q){return ResultUtils.success(service.list(users.getLoginUser(q)));}}
